import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { configApi, departmentsApi, subjectsApi, facultyApi, timetablesApi } from '../services/api';
import './Dashboard.css';

function Dashboard() {
  const [config, setConfig] = useState(null);
  const [departments, setDepartments] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [faculty, setFaculty] = useState([]);
  const [timetables, setTimetables] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    Promise.all([
      configApi.get().catch(() => null),
      departmentsApi.getAll().catch(() => []),
      subjectsApi.getAll().catch(() => []),
      facultyApi.getAll().catch(() => []),
      timetablesApi.getAll().catch(() => [])
    ]).then(([c, d, s, f, t]) => {
      setConfig(c);
      setDepartments(d);
      setSubjects(s);
      setFaculty(f);
      setTimetables(t);
      setLoading(false);
    }).catch(() => {
      setError('Failed to load data');
      setLoading(false);
    });
  }, []);

  if (loading) return <div className="page-loading">Loading...</div>;
  if (error) return <div className="alert alert-error">{error}</div>;

  const days = config?.workingDays?.length || 0;
  const periods = config?.periodsPerDay || 0;

  return (
    <div className="dashboard">
      <h1>Dashboard</h1>
      <p className="dashboard-subtitle">Overview of your College Timetable Generator</p>

      <div className="dashboard-cards">
        <Link to="/config" className="dashboard-card">
          <span className="dashboard-card-icon">⚙</span>
          <div>
            <h3>Academic Config</h3>
            <p>{days} days × {periods} periods</p>
          </div>
        </Link>
        <Link to="/departments" className="dashboard-card">
          <span className="dashboard-card-icon">🏛</span>
          <div>
            <h3>Departments</h3>
            <p>{departments.length} department(s)</p>
          </div>
        </Link>
        <Link to="/subjects" className="dashboard-card">
          <span className="dashboard-card-icon">📚</span>
          <div>
            <h3>Subjects</h3>
            <p>{subjects.length} subject(s)</p>
          </div>
        </Link>
        <Link to="/faculty" className="dashboard-card">
          <span className="dashboard-card-icon">👤</span>
          <div>
            <h3>Faculty</h3>
            <p>{faculty.length} faculty member(s)</p>
          </div>
        </Link>
        <Link to="/timetables" className="dashboard-card">
          <span className="dashboard-card-icon">📅</span>
          <div>
            <h3>Timetables</h3>
            <p>{timetables.length} timetable(s) generated</p>
          </div>
        </Link>
      </div>

      <div className="dashboard-quick">
        <h2>Quick Start</h2>
        <ol>
          <li>Set <Link to="/config">Academic Configuration</Link> (working days & periods per day).</li>
          <li>Add <Link to="/departments">Departments</Link> with section counts.</li>
          <li>Add <Link to="/faculty">Faculty</Link> with workload limits.</li>
          <li>Add <Link to="/subjects">Subjects</Link> per semester/department and assign faculty.</li>
          <li>Go to <Link to="/timetables">Timetables</Link> and generate for a semester.</li>
        </ol>
      </div>
    </div>
  );
}

export default Dashboard;
